use vstd::prelude::*;

verus! {
    /// Reverse a Vec by consuming it, mirroring `m.into_iter().rev().collect()`.
    fn flipud(m: Vec<f32>) -> Vec<f32>
        ensures
            // same length
            result.len() == m.len(),
            // for every index i in 0..len, result[i] == m[len-1-i]
            forall |i: nat|
                i < m.len() ==>
                result.as_seq()[i] == m.as_seq()[m.len() - 1 - i],
    {
        // the implementation stays exactly the same
        m.into_iter().rev().collect()
    }
}

